// Bundle the skill into the Worker so the site can serve it (src/skill-files.ts is generated; do not edit it).
// Wrangler runs this before dev and deploy (see "build" in wrangler.jsonc); the burn tests check it is fresh.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const SKILL_FILES = ["SKILL.md", "SKILL.en.md", "scripts/burn.mjs", "scripts/resethook.mjs", "references/webhook.md", "references/webhook.en.md"];
const root = join(dirname(fileURLToPath(import.meta.url)), "..");

export function render() {
  const files = Object.fromEntries(SKILL_FILES.map((f) => [f, readFileSync(join(root, "skill/resethook", f), "utf8")]));
  return `// generated by scripts/bundle-skill.mjs from skill/resethook; do not edit\nexport const SKILL_FILES: Record<string, string> = ${JSON.stringify(files, null, 1)};\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) writeFileSync(join(root, "src/skill-files.ts"), render());
